package com.airesumebuilder.feature.pdf.service;
import com.airesumebuilder.feature.pdf.repository.PdfExportRepository.ResumeDocument;import org.openpdf.text.*;import org.openpdf.text.pdf.PdfWriter;import java.io.ByteArrayOutputStream;import org.springframework.stereotype.Component;
@Component public class PdfRenderer{public byte[]render(ResumeDocument resume){try{ByteArrayOutputStream out=new ByteArrayOutputStream();Document document=new Document(PageSize.A4,48,48,48,48);PdfWriter.getInstance(document,out);document.open();document.add(new Paragraph(safe(resume.fullName()),FontFactory.getFont(FontFactory.HELVETICA_BOLD,20)));document.add(new Paragraph(safe(resume.targetJobTitle()),FontFactory.getFont(FontFactory.HELVETICA,12)));document.add(Chunk.NEWLINE);document.add(new Paragraph(safe(resume.title()),FontFactory.getFont(FontFactory.HELVETICA_BOLD,16)));document.add(new Paragraph(safe(resume.summary()),FontFactory.getFont(FontFactory.HELVETICA,11)));document.close();return out.toByteArray();}catch(Exception e){throw new IllegalStateException("PDF generation failed.",e);}}private String safe(String s){return s==null?"":s.replaceAll("[\\p{Cntrl}&&[^\\r\\n\\t]]","");}}
